-- Loyalty alliances and programs for the checked tourism reference (step 3 of 3).
-- Directory only: no user rows, no card numbers, no membership numbers.
-- Those values stay in Telegram CloudStorage and have no columns here.
--
-- Program zone: green only when verified is true and source_is_official is true.
-- verified is true only when an explicit verified flag cites an official URL
-- (enrolment page, or russian_citizens.source). A nested can_join verified flag
-- without that URL stays in can_join_verified and leaves the row yellow.
-- Alliance zone: green only when promo_url is an official alliance page and
-- promo is a concrete offer. Unknown or secondary promos stay yellow.
-- legacy keeps the original object and is not granted to anon or authenticated.
--
-- The seed statement below is generated by scripts/seed_loyalty_programs.py.
-- Merging this file to main runs .github/workflows/supabase_deploy.yml against production.
-- Do not apply it before the owner says so.

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS public.loyalty_alliances (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    slug text NOT NULL,
    name text NOT NULL,
    our_members jsonb NOT NULL DEFAULT '[]'::jsonb,
    promo text,
    promo_url text,
    status_match text,
    source_url text,
    zone text NOT NULL CHECK (zone IN ('green', 'yellow')),
    checked_at date NOT NULL,
    legacy jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT loyalty_alliances_slug_key UNIQUE (slug),
    CONSTRAINT loyalty_alliances_slug_format CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$')
);

CREATE TABLE IF NOT EXISTS public.loyalty_programs (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    slug text NOT NULL,
    airline text NOT NULL,
    iata text NOT NULL,
    program_name text NOT NULL,
    alliance_slug text NOT NULL REFERENCES public.loyalty_alliances (slug) ON UPDATE CASCADE,
    alliance_label text NOT NULL,
    currency text,
    enrolment_url text,
    enrolment_url_verified boolean NOT NULL,
    mile_expiry text,
    mile_expiry_source text,
    key_partners text,
    can_join text,
    can_join_basis text,
    can_join_source text,
    can_join_verified boolean,
    status_match text,
    promos_url text,
    notes text,
    source_url text,
    source_is_official boolean NOT NULL,
    verified boolean NOT NULL,
    zone text NOT NULL CHECK (zone IN ('green', 'yellow')),
    checked_at date NOT NULL,
    disclaimer text NOT NULL,
    legacy jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT loyalty_programs_slug_key UNIQUE (slug),
    CONSTRAINT loyalty_programs_slug_format CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$')
);

COMMENT ON TABLE public.loyalty_programs IS
    'Loyalty program directory. No member numbers and no user records.';
COMMENT ON COLUMN public.loyalty_programs.verified IS
    'True only when an explicit verified flag cites an official URL.';
COMMENT ON COLUMN public.loyalty_programs.zone IS
    'green when verified and source_is_official; otherwise yellow.';

-- Postgres does not index foreign-key columns.
CREATE INDEX IF NOT EXISTS idx_loyalty_programs_alliance_slug
    ON public.loyalty_programs (alliance_slug);
CREATE INDEX IF NOT EXISTS idx_loyalty_programs_zone
    ON public.loyalty_programs (zone);
CREATE INDEX IF NOT EXISTS idx_loyalty_programs_checked_at
    ON public.loyalty_programs (checked_at);
CREATE INDEX IF NOT EXISTS idx_loyalty_alliances_zone
    ON public.loyalty_alliances (zone);

ALTER TABLE public.loyalty_alliances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.loyalty_programs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS loyalty_alliances_public_read ON public.loyalty_alliances;
CREATE POLICY loyalty_alliances_public_read ON public.loyalty_alliances
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS loyalty_programs_public_read ON public.loyalty_programs;
CREATE POLICY loyalty_programs_public_read ON public.loyalty_programs
    FOR SELECT
    TO anon, authenticated
    USING (true);

-- Data API: since 2026-10-30 new public tables get no default grants.
-- Writes stay on service_role. legacy is the original object, including
-- secondary notes. anon and authenticated have no SELECT on that column.
-- A role with column privileges cannot use SELECT * on the table.
-- The public views are the select=* shape: no legacy column, security invoker,
-- and the underlying RLS policies still apply.
REVOKE ALL ON TABLE public.loyalty_alliances, public.loyalty_programs FROM PUBLIC;
REVOKE ALL ON TABLE public.loyalty_alliances, public.loyalty_programs FROM anon, authenticated;

GRANT SELECT (
    id,
    slug,
    name,
    our_members,
    promo,
    promo_url,
    status_match,
    source_url,
    zone,
    checked_at,
    created_at,
    updated_at
) ON TABLE public.loyalty_alliances TO anon, authenticated;

GRANT SELECT (
    id,
    slug,
    airline,
    iata,
    program_name,
    alliance_slug,
    alliance_label,
    currency,
    enrolment_url,
    enrolment_url_verified,
    mile_expiry,
    mile_expiry_source,
    key_partners,
    can_join,
    can_join_basis,
    can_join_source,
    can_join_verified,
    status_match,
    promos_url,
    notes,
    source_url,
    source_is_official,
    verified,
    zone,
    checked_at,
    disclaimer,
    created_at,
    updated_at
) ON TABLE public.loyalty_programs TO anon, authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.loyalty_alliances, public.loyalty_programs TO service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;

DROP VIEW IF EXISTS public.loyalty_alliances_public;
CREATE VIEW public.loyalty_alliances_public
WITH (security_invoker = true) AS
SELECT
    id,
    slug,
    name,
    our_members,
    promo,
    promo_url,
    status_match,
    source_url,
    zone,
    checked_at,
    created_at,
    updated_at
FROM public.loyalty_alliances;

DROP VIEW IF EXISTS public.loyalty_programs_public;
CREATE VIEW public.loyalty_programs_public
WITH (security_invoker = true) AS
SELECT
    id,
    slug,
    airline,
    iata,
    program_name,
    alliance_slug,
    alliance_label,
    currency,
    enrolment_url,
    enrolment_url_verified,
    mile_expiry,
    mile_expiry_source,
    key_partners,
    can_join,
    can_join_basis,
    can_join_source,
    can_join_verified,
    status_match,
    promos_url,
    notes,
    source_url,
    source_is_official,
    verified,
    zone,
    checked_at,
    disclaimer,
    created_at,
    updated_at
FROM public.loyalty_programs;

REVOKE ALL ON TABLE public.loyalty_alliances_public, public.loyalty_programs_public FROM PUBLIC;
REVOKE ALL ON TABLE public.loyalty_alliances_public, public.loyalty_programs_public FROM anon, authenticated;
GRANT SELECT ON TABLE public.loyalty_alliances_public, public.loyalty_programs_public TO anon, authenticated;

